import type { VariableConfig } from '../../Variable';
/**
 * Configuration type for attachment variables
 */
export type AttachmentVariableType<Type = File | string, Default extends Type = Type> = VariableConfig<Type, Default>;
/**
 * A Variable for an attachment field.
 *
 * @see https://docs.servicenow.com/csh?topicname=variable-types.html&version=latest
 *
 * @param config - Configuration for the attachment variable including:
 *   * **question** - Question text displayed to the user
 *   * **mandatory** - Whether the attachment is mandatory
 *   * **hidden** - Whether the attachment is hidden
 *   * **readOnly** - Whether the attachment is read only
 *   * And all other properties from the base Variable type
 */
export declare function AttachmentVariable(config: AttachmentVariableType): AttachmentVariableType<string | File, string | File>;
